INSERT INTO `campaigns` (`id`, `campaign_group_id`, `email`, `subject`, `url`, `message`, `created_at`, `updated_at`, `deleted_at`)
VALUES
	(1,1,'matt@papercode.co.uk','Test Campaign','google.com','Dear SACRE clerk\n \nThank you for renewing your annual membership subscription to NASACRE for the year 2022-23. The log-in details were changed earlier today and the **user name and password** have been updated for the new academic year.\nMost areas of the website are open to all, but the log-in is required to access parts of the Resources section.\n \nAs a member SACRE, **you can share the log-in details below with your SACRE members.**\n \n**IT IS VERY IMPORTANT THAT YOU KEEP THESE DETAILS SAFE.**\n \n**New log in details:**\n \n**Username:**\n**members2223**\n \n**Password:**\n**22N@sAcRE23**\n \nKind regards\n \nMarie Cooper\nNASACRE Administrator','2020-09-18 15:14:08','2022-09-07 09:40:18',NULL),
	(2,1,'matt@designbyz3.co.uk','Another Test Campaign','facebook.com','Hello there!','2020-09-20 12:10:26','2020-09-20 12:10:26',NULL),
	(3,22,'admin@nasacre.org.uk','NASACRE Username and Password Change','https://nasacre.org.uk','Dear SACRE clerk\n \nThank you for renewing your annual membership subscription to NASACRE for the year 2026-27. The log-in details were changed earlier today and the **user name and password** have been updated for the new academic year.\nMost areas of the website are open to all, but the log-in is required to access the subscribers\' area.\n \nAs a subscribed member SACRE, **you can share the log-in details below with your SACRE members.**\n \n**IT IS VERY IMPORTANT THAT YOU KEEP THESE DETAILS SAFE.**\n \n**New log in details:**\n \n**Username:**\n**members**\n \n**Password:**\n**2627EdUc@Ti0nRE!**\n \nKind regards\n \nMarie Cooper\nNASACRE Administrator','2022-09-07 09:44:06','2026-09-01 19:08:50',NULL),
	(4,6,'admin@nasacre.org.uk','Inter Faith Week 2024','https://nasacre.org.uk','Dear SACREs,\n \nInter Faith Week 2024 is next week, running from 10th- 17th November\n \nThe Inter Faith week education website can be found here: \n \n[https://www.ifw4schools.co.uk](http://)\n \n \nThe Education theme this year is: ‘Sharing My Story, Building Our Future’\naiming to foster empathy, understanding, and social cohesion among students while enriching their knowledge of diverse faiths and beliefs! \n \nThe website includes links to events and resources to help your students to engage with the theme.\n \nPlease remind all your schools. If they or you have photos or stories to share about activities taking place during the week , please encourage them to contact the IF week for schools web team on the link on the site and celebrate their activities to a wider audience.\n \nEnjoy the week!\n \nCo- Chairs at NASACRE','2024-11-08 13:22:27','2024-11-08 13:22:27',NULL);
