INSERT INTO `invoices` (`id`, `email`, `subs`, `date`, `year`, `from`, `message`, `created_at`, `updated_at`, `deleted_at`, `batch`)
VALUES
	(1,'admin@nasacre.org.uk',105.00,'2020-09-01 15:49:00',2020,'admin@nasacre.org.uk','**This email is being sent to:**\n\n\n- All SACRE clerks. *Where there is no SACRE clerk listed, this email will be sent to another SACRE Officer.*\n- Where we have received the information, this email is also being sent to the finance department or paying authority.\n\n**Please read the important information below.**\n\nDear SACRE clerk\n\nPlease find attached the invoice for your SACRE\'s Annual Subscription to NASACRE for the Academic Year 2020-21. We will change the user name and password for the \"members only\" pages of the NASACRE website on September 1st.  Only those SACREs which have paid their 2020-21 subscription will be given the new access information.\n\nThese invoices are being sent using an automated system. Though not perfect, it saves time and is more cost effective.\n\n**Invoice addresses and Purchase Order numbers**\nIf an invoice address and/or Purchase Order number is required and we have already been provided with details, they have been added to your invoice. If you now need to raise a PO number, this will be added to your invoice when we receive this information.\n\n**Payment of invoices**\nInvoices are being sent in June to ensure that payment is received **by 31st August**. \n\nReceipt of payment, and therefore membership of NASACRE, will be indicated by a small NASACRE logo next to your SACREâs name in the [SACRE Directory](http://nasacre.org.uk/database). As payments are received, the Directory will be updated.**Please check your membership status in the Directory from time to time. If there is no NASACRE membership logo, please check progress of the payment with your finance department, or contact the Treasurer.** \n\nWe would ask that wherever possible, if payment is made by BACS, **separate Remittance Advice**  is also sent to us. It is sometimes very difficult to ascertain from our bank statements which local authority has made payment when the payer is identified only by a random string of numbers or a series of letters which could apply to several different local authorities. \n\nPlease can we remind you to check your SACREs contact details on our website and let us know of any updates required.\n\nKind regards\n**Marie Cooper**\n**NASACRE Administrator**','2020-09-22 15:49:40','2020-10-05 13:30:27',NULL,6),
	(2,'admin@nasacre.org.uk',105.00,'2022-07-12 11:16:00',2022,'admin@nasacre.org.uk','**This email is being sent to:**\n\n\n- All SACRE clerks. *Where there is no SACRE clerk listed, this email will be sent to another SACRE Officer.*\n- Where we have received the information, this email is also being sent to the finance department or paying authority.\n\n**Please read the important information below.**\n\nDear SACRE clerk\n\nPlease find attached the invoice for your SACRE\'s Annual Subscription to NASACRE for the Academic Year 2022-23. We will change the user name and password for the \"members only\" pages of the NASACRE website on September 1st.  Only those SACREs which have paid their 2022-23 subscription will be given the new access information.\n\nThese invoices are being sent using an automated system. Though not perfect, it saves time and is more cost effective.\n\n**Invoice addresses and Purchase Order numbers**\nIf an invoice address and/or Purchase Order number is required and we have already been provided with details, they have been added to your invoice. If you now need to raise a PO number, this will be added to your invoice when we receive this information.\n\n**Option to add virtual training package fee**\nThis year we are giving SACRE\'s the option to add the £50 virtual training package fee for 2022-23 on to the same invoice as the membership fee. More information on the training package can be found [here](https://nasacre.org.uk/training-and-support/) on our website. If you would like the package to be added to your invoice please email admin@nasacre.org.uk to request this. We will then send you an amended invoice.\n\n\n**Payment of invoices**\nInvoices are being sent in July to ensure that payment is received **by 31st August**. \n\nReceipt of payment, and therefore membership of NASACRE, will be indicated by a small NASACRE logo next to your SACREs name in the [SACRE Directory](http://nasacre.org.uk/database). As payments are received, the Directory will be updated.**Please check your membership status in the Directory from time to time. If there is no NASACRE membership logo, please check progress of the payment with your finance department, or contact the Treasurer.** \n\nWe would ask that wherever possible, if payment is made by BACS, **separate Remittance Advice**  is also sent to us. It is sometimes very difficult to ascertain from our bank statements which local authority has made payment when the payer is identified only by a random string of numbers or a series of letters which could apply to several different local authorities. \n\nPlease can we remind you to check your SACREs contact details on our website and let us know of any updates required.\n\nKind regards\n**Marie Cooper**\n**NASACRE Administrator**','2022-07-11 11:17:03','2022-07-12 11:31:17',NULL,2),
	(3,'admin@nasacre.org.uk',105.00,'2023-07-04 14:56:00',2023,'admin@nasacre.org.uk','**This email is being sent to:**\n\n\n- All SACRE clerks. *Where there is no SACRE clerk listed, this email will be sent to another SACRE Officer.*\n- Where we have received the information, this email is also being sent to the finance department or paying authority.\n\n**Please read the important information below.**\n\nDear SACRE clerk\n\nPlease find attached the invoice for your SACRE\'s Annual Subscription to NASACRE for the Academic Year 2023-24. We will change the user name and password for the \"members only\" pages of the NASACRE website on September 1st.  Only those SACREs which have paid their 2023-24 subscription will be given the new access information.\n\nThese invoices are being sent using an automated system. Though not perfect, it saves time and is more cost effective.\n\n**Invoice addresses and Purchase Order numbers**\nIf an invoice address and/or Purchase Order number is required and we have already been provided with details, they have been added to your invoice. If you now need to raise a PO number, this will be added to your invoice when we receive this information.\n\n**Option to add virtual training package fee**\nThis year we are giving SACRE\'s the option to add the £50 virtual training package fee for 2023-24 on to the same invoice as the membership fee. More information on the training package can be found [here](https://nasacre.org.uk/training-and-support/) on our website. If you would like the package to be added to your invoice please email admin@nasacre.org.uk to request this. We will then send you an amended invoice.\n\n\n**Payment of invoices**\nInvoices are being sent in July to ensure that payment is received **by 31st August**. \n\nReceipt of payment, and therefore membership of NASACRE, will be indicated by a small NASACRE logo next to your SACREs name in the [SACRE Directory](http://nasacre.org.uk/database). As payments are received, the Directory will be updated. **Please check your membership status in the Directory from time to time. If there is no NASACRE membership logo, please check progress of the payment with your finance department, or contact admin@nasacre.org.uk.** \n\nWe would ask that wherever possible, if payment is made by BACS, **separate Remittance Advice**  is also sent to us. It is sometimes very difficult to ascertain from our bank statements which local authority has made payment when the payer is identified only by a random string of numbers or a series of letters which could apply to several different local authorities. \n\nPlease can we remind you to check your SACRE\'s contact details on our website and let us know of any updates required. **All SACRE details are in the public domain** so, where possible, should not include personal addresses.  **If that isn\'t possible please ensure you first have a contact\'s express permission before supplying us with their personal email address.** \n\nKind regards\n**Marie Cooper**\n**NASACRE Administrator**','2023-06-23 15:58:01','2023-07-04 12:01:54',NULL,1),
	(4,'admin@nasacre.org.uk',115.00,'2024-07-12 17:06:00',2024,'admin@nasacre.org.uk','**This email is being sent to:**\n\n\n- All SACRE clerks. *Where there is no SACRE clerk listed, this email will be sent to another SACRE Officer.*\n- Where we have received the information, this email is also being sent to the finance department or paying authority.\n\n**Please read the important information below.**\n\nDear SACRE clerk\n\nPlease find attached the invoice for your SACRE\'s Annual Subscription to NASACRE for the Academic Year 2024-25. We will change the user name and password for the \"members only\" pages of the NASACRE website on September 1st.  Only those SACREs which have paid their 2024-25 subscription will be given the new access information.\n\nThese invoices are being sent using an automated system. Though not perfect, it saves time and is more cost effective.\n\n**Invoice addresses and Purchase Order numbers**\nIf an invoice address and/or Purchase Order number is required and we have already been provided with details, they have been added to your invoice. If you now need to raise a PO number, this will be added to your invoice when we receive this information.\n\n**Option to add virtual training package fee**\nThis year we are giving SACRE\'s the option to add the £60 virtual training package fee for 2024-25 on to the same invoice as the membership fee. More information on the training package can be found [here](https://nasacre.org.uk/training-and-support/) on our website. If you would like the package to be added to your invoice please email admin@nasacre.org.uk to request this. We will then send you an amended invoice.\n\n\n**Payment of invoices**\nInvoices are being sent in July to ensure that payment is received **by 31st August**. \n\nReceipt of payment, and therefore membership of NASACRE, will be indicated by a small NASACRE logo next to your SACREs name in the [SACRE Directory](http://nasacre.org.uk/database). As payments are received, the Directory will be updated. **Please check your membership status in the Directory from time to time. If there is no NASACRE membership logo, please check progress of the payment with your finance department, or contact admin@nasacre.org.uk.** \n\nWe would ask that wherever possible, if payment is made by BACS, **separate Remittance Advice**  is also sent to us. It is sometimes very difficult to ascertain from our bank statements which local authority has made payment when the payer is identified only by a random string of numbers or a series of letters which could apply to several different local authorities. \n\nPlease can we remind you to check your SACRE\'s contact details on our website and let us know of any updates required. **All SACRE details are in the public domain** so, where possible, should not include personal addresses.  **If that isn\'t possible please ensure you first have a contact\'s express permission before supplying us with their personal email address.** \n\nKind regards\n**Marie Cooper**\n**NASACRE Administrator**','2024-06-25 18:08:43','2024-07-12 13:29:44',NULL,1),
	(5,'admin@nasacre.org.uk',115.00,'2025-07-02 17:42:00',2025,'admin@nasacre.org.uk','**This email is being sent to:**\n\n- All SACRE clerks. *Where there is no SACRE clerk listed, this email will be sent to another SACRE Officer.*\n\n**Please read the important information below.**\n\nDear SACRE clerk\n\nPlease find attached the invoice for your SACRE\'s Annual Subscription to NASACRE for the Academic Year 2025-26. We will change the user name and password for the \"members only\" pages of the NASACRE website on September 1st.  Only those SACREs which have paid their 2025-26 subscription will be given the new access information.\n\nThese invoices are being sent using an automated system. Though not perfect, it saves time and is more cost effective.\n\n**Option to add virtual training package fee**\nWe are giving SACRE\'s the option to add the £60 virtual training package fee for 2025-26 on to the same invoice as the membership fee. More information on the training package can be found [here](https://nasacre.org.uk/training-and-support/) on our website. If you would like the package to be added to your invoice please email admin@nasacre.org.uk to request this. We will then send you an amended invoice.\n\n**Invoice addresses and Purchase Order numbers**\nIf an invoice address and/or Purchase Order number is required and we have already been provided with details, they have been added to your invoice. If you now need to raise a PO number, this will be added to your invoice when we receive this information.\n\n**Payment of invoices**\nInvoices are being sent in July to ensure that payment is received **by 31st August**. \n\n**PLEASE ENSURE PAYMENT IS MADE TO OUR NEW BANK ACCOUNT AS SHOWN ON YOUR INVOICE**\n\nReceipt of payment, and therefore membership of NASACRE, will be indicated by a small NASACRE logo next to your SACREs name in the [SACRE Directory](http://nasacre.org.uk/database). As payments are received, the Directory will be updated. **Please check your membership status in the Directory from time to time. If there is no NASACRE membership logo, please check progress of the payment with your finance department, or contact admin@nasacre.org.uk.** \n\nWe would ask that wherever possible, if payment is made by BACS, **separate Remittance Advice**  is also sent to us. It is sometimes very difficult to ascertain from our bank statements which local authority has made payment when the payer is identified only by a random string of numbers or a series of letters which could apply to several different local authorities. \n\nPlease can we remind you to check your SACRE\'s contact details on our website and let us know of any updates required. **All SACRE details are in the public domain** so, where possible, should not include personal addresses.  **If that isn\'t possible please ensure you first have a contact\'s express permission before supplying us with their personal email address.** \n\nKind regards\n**Marie Cooper**\n**NASACRE Administrator**','2025-06-30 17:52:01','2025-07-02 16:13:20',NULL,1),
	(6,'admin@nasacre.org.uk',185.00,'2026-06-24 11:09:00',2026,'admin@nasacre.org.uk','**This email is being sent to:**\n\n- All SACRE clerks. *Where there is no SACRE clerk listed, this email will be sent to another SACRE Officer.*\n\n**Please read the important information below.**\n\nDear SACRE clerk\n\nPlease find attached the invoice for your SACRE\'s Annual Subscription to NASACRE for the Academic Year 2026-27. We will change the user name and password for the subscribers area of the NASACRE website on September 1st.  Only those SACREs which have paid their 2026-27 subscription will be given the new access information.\n\nThese invoices are being sent using an automated system. Though not perfect, it saves time and is more cost effective.\n\n**The virtual training package is now included in this fee**\nMore information on the training package can be found [here](https://nasacre.org.uk/training-and-support/) on our website. \n\n**Purchase Order numbers**\nIf a Purchase Order number is required and we have already been provided with details, we will add this and resend the invoice to you as soon as possible. If you now need to raise a PO number, this will be added to your invoice when we receive this information.\n\n**Payment of invoices**\nInvoices are being sent in June to ensure that payment is received **by 31st August**. \n\n**PLEASE ENSURE PAYMENT IS MADE TO OUR NEW BANK ACCOUNT AS SHOWN ON YOUR INVOICE**\n\nReceipt of payment, and therefore membership of NASACRE, will be indicated by a small coloured NASACRE logo next to your SACREs name in the [SACRE Directory](http://nasacre.org.uk/database). As payments are received, the Directory will be updated. **Please check your membership status in the Directory from time to time. If there is not a coloured NASACRE membership logo, please check progress of the payment with your finance department, or contact admin@nasacre.org.uk. If the logo is grey, this means you were a member for 2025-26 but not yet for 2026-27** \n\nWe would ask that wherever possible, if payment is made by BACS, **separate Remittance Advice**  is also sent to us. It is sometimes very difficult to ascertain from our bank statements which local authority has made payment when the payer is identified only by a random string of numbers or a series of letters which could apply to several different local authorities. \n\nPlease can we remind you to check your SACRE\'s contact details on our website and let us know of any updates required. **All SACRE details are in the public domain** so, where possible, should not include personal addresses.  **If that isn\'t possible please ensure you first have a contact\'s express permission before supplying us with their personal email address.** \n\nKind regards\n**Marie Cooper**\n**NASACRE Administrator**','2026-06-24 11:11:00','2026-06-26 08:49:04',NULL,1);
